import ("context"; "time"; "github.com/google/uuid"
        "github.com/redis/go-redis/v9")

// 加锁:SET NX EX + 唯一 token
func Lock(ctx context.Context, key string, ttl time.Duration) (string, bool) {
    token := uuid.NewString()
    ok, _ := rdb.SetNX(ctx, key, token, ttl).Result()
    if ok { return token, true }
    return "", false
}

// 释放:Lua 保证「校验 token + 删除」原子
var unlockScript = redis.NewScript(`
  if redis.call('get', KEYS[1]) == ARGV[1] then
    return redis.call('del', KEYS[1])
  else return 0 end`)

func Unlock(ctx context.Context, key, token string) error {
    return unlockScript.Run(ctx, rdb, []string{key}, token).Err()
}

