// 核心逻辑一样:唯一 token + 原子释放。这里展示 Lua 脚本的调用
std::string lock(redis::Client& r, const std::string& key, int ttl) {
    std::string token = gen_uuid();
    // SET key token NX EX ttl —— 原子的抢锁+过期
    auto ok = r.set(key, token, redis::SetOpts{}.nx().ex(ttl));
    return ok ? token : "";
}

bool unlock(redis::Client& r, const std::string& key,
            const std::string& token) {
    static const char* lua =
        "if redis.call('get',KEYS[1])==ARGV[1] then "
        "return redis.call('del',KEYS[1]) else return 0 end";
    return r.eval(lua, {key}, {token}) == 1;
}
